def common(name, classification, transaction, requirements, steps, fees, total, people):
    return {"plain_language_name": name, "classification": classification, "type_of_transaction": transaction, "requirements": requirements, "client_steps": steps, "fees": fees, "processing_time": total, "person_responsible": people}

