eligibility = {
    "Truck Ban and Total Truck Ban Exemption Certificate Issuance": "Truck owners, operators, businesses, and establishments requesting an exemption",
    "Request for Research/Photo or Video Documentation/Tour": "Researchers, students, visitors, organizations, and members of the general public",
    "Free Legal Consultation": "City government offices, officials, employees, and clients seeking legal guidance",
}

data=json.loads(PATH.read_text(encoding="utf-8")); found=set()
for item in data["services"]:
    name=item.get("service_name")
    if name in updates:
        item.update(updates[name])
        if name in eligibility:
            item["who_may_avail"] = eligibility[name]
        found.add(name)
missing=set(updates)-found
if missing: raise SystemExit(f"Services not found: {sorted(missing)}")
PATH.write_text(json.dumps(data,indent=2,ensure_ascii=False),encoding="utf-8")
print(f"Transcribed {len(found)} final Charter services")
